    await this.ipc.portfolio.create({ name: this.portfolioForm.value.name, baseCurrency: 'BRL' });
    await this.load();
  }

  async createTx() {
    await this.ipc.portfolio.createTransaction(this.txForm.getRawValue());
    await this.load();
  }
